// Robo Academy course: from "what is electricity?" to an AI robot with its own web app.
// 6 stages, 24 weeks, 5 lessons a week (one a day), then a weekly test that earns a passport stamp.
// Each week lists the parts it needs, so learners can order them a week ahead.
//
// L(title, emoji, concept, keyFacts, missionSteps, exercises, youtubeSearch, questions, extras)
//   keyFacts / missionSteps:  'a|b|c'
//   exercises:                'Question => Answer|Question => Answer'
//   questions:                ['Question|right answer|wrong|wrong', ...]
//   extras:                   { toy, code, fun }   toy = ohm | resistor | binary | logic | pwm

function L(t, e, c, k, m, x, yt, q, o = {}) {
  return {
    t, e, c,
    k: k.split('|'),
    m: m.split('|'),
    x: x.split('|').map(s => s.split(' => ')),
    yt,
    q: q.map(s => { const [qq, a, ...w] = s.split('|'); return { q: qq, a, w }; }),
    ...o
  };
}

